// Factory wavetables, generated by code on first use (no binary assets). Pure (Node-safe).
// Every table is a list of FRAME_SIZE-sample single cycles, band-limited at generation (additive synthesis or
// oversampled + spectrally truncated time-domain shapes) and normalized per table.
import { rng32 } from '../dsp/fft.js';
import { FRAME_SIZE, frameFromHarmonics, bandlimit, normalizeFrames, morphKeys, removeDC } from './tables.js';

const H = FRAME_SIZE / 2 - 1;
const N = 64; // frames of a morph table
const TAU = Math.PI * 2;

// ------------------------------------------------------------------------------------------- spectra
const spec = (fn, top = H) => { const a = new Float32Array(top + 1); for (let k = 1; k <= top; k++) a[k] = fn(k); return a; };
const SAW = (k) => 1 / k;
const SQUARE = (k) => (k % 2 ? 1 / k : 0);
const TRI = (k) => (k % 2 ? (((k - 1) / 2) % 2 ? -1 : 1) / (k * k) : 0);
const sine = () => frameFromHarmonics(spec((k) => (k === 1 ? 1 : 0), 1));
const saw = () => frameFromHarmonics(spec(SAW));
const square = () => frameFromHarmonics(spec(SQUARE));
const tri = () => frameFromHarmonics(spec(TRI));
const pulse = (w) => frameFromHarmonics(spec((k) => Math.sin(Math.PI * k * w) / k), spec((k) => Math.PI / 2));
/** n frames: frame i from additive spectrum fn(k, t) with t = i/(n-1). */
const sweep = (fn, n = N, phases = null) => Array.from({ length: n }, (_, i) => frameFromHarmonics(spec((k) => fn(k, n > 1 ? i / (n - 1) : 0)), phases ? phases(i) : null));
/** n frames from a time-domain shape f(phase, t), band-limited. */
const shape = (f, n = N) => Array.from({ length: n }, (_, i) => bandlimit((x) => f(x, n > 1 ? i / (n - 1) : 0)));

// 2-pole low-pass magnitude at harmonic k for cutoff c (harmonics) and resonance q
const lp2 = (k, c, q = 0.707) => { const r = k / c; return 1 / Math.sqrt((1 - r * r) ** 2 + (r / q) ** 2); };

// formant envelope: sum of resonances (Hz) evaluated for harmonic k of a ~110 Hz voice
const F0 = 110;
const VOWELS = {
  a: [[730, 90, 1], [1090, 110, 0.5], [2440, 160, 0.25], [3400, 250, 0.08]],
  e: [[530, 80, 1], [1840, 120, 0.45], [2480, 160, 0.3], [3500, 250, 0.1]],
  i: [[270, 60, 1], [2290, 130, 0.35], [3010, 170, 0.3], [3700, 250, 0.1]],
  o: [[570, 80, 1], [840, 100, 0.6], [2410, 160, 0.12], [3300, 250, 0.05]],
  u: [[300, 60, 1], [870, 100, 0.35], [2240, 160, 0.08], [3300, 250, 0.03]],
};
const formantAmp = (k, forms, tilt = 1) => {
  const f = k * F0;
  let a = 0;
  for (const [fc, bw, g] of forms) a += g / (1 + ((f - fc) / bw) ** 2);
  return (a + 0.004) / Math.pow(k, tilt * 0.6);
};
const lerpForms = (A, B, t) => A.map(([f, b, g], j) => [f + (B[j][0] - f) * t, b + (B[j][1] - b) * t, g + (B[j][2] - g) * t]);
const vowelPath = (seq, n = N) => sweep((k, t) => {
  const x = t * (seq.length - 1), j = Math.min(seq.length - 2, Math.floor(x));
  return formantAmp(k, lerpForms(VOWELS[seq[j]], VOWELS[seq[j + 1]], x - j));
}, n, null);

// phase modulation: carrier ratio c, modulator ratio m, index I (+ feedback)
const pm = (c, m, I) => (x) => Math.sin(TAU * c * x + I * Math.sin(TAU * m * x));
const fbOsc = (beta) => (x) => {
  // feedback FM (DX op 1): y = sin(θ + β y) solved by fixed-point iteration (smooth for β < ~1.6)
  let y = 0;
  for (let i = 0; i < 12; i++) y = Math.sin(TAU * x + beta * y);
  return y;
};

// deterministic random
const rnd = (seed) => rng32(seed);
const gauss = (r) => { let s = 0; for (let i = 0; i < 6; i++) s += r(); return s / 6; };

// PADsynth-like single cycles: harmonic profile with gaussian-shaped, randomly jittered partial amplitudes
const padFrames = (seed, profile, n = 32, drift = 0.35) => {
  const r = rnd(seed);
  const base = spec(profile, 256);
  const jit = Array.from({ length: n }, () => spec(() => 1 - drift + 2 * drift * gauss(r), 256));
  const ph = spec(() => r() * TAU, 256);
  return Array.from({ length: n }, (_, i) => frameFromHarmonics(spec((k) => base[k] * jit[i][k], 256), ph.map((p, k) => p + i * 0.07 * k)));
};

const quant = (v, bits) => { const s = 2 ** (bits - 1); return Math.round(v * s) / s; };

// ------------------------------------------------------------------------------------------- catalogue
/** { id: { name, category, gen() -> Float32Array[] } } */
export const FACTORY_TABLES = {
  // ---- Basic
  basic: { name: 'Basic Shapes', category: 'Basic', gen: () => morphKeys([sine(), tri(), saw(), square()], N) },
  'sine-saw': { name: 'Sine → Saw', category: 'Basic', gen: () => morphKeys([sine(), saw()], N) },
  'sine-square': { name: 'Sine → Square', category: 'Basic', gen: () => morphKeys([sine(), square()], N) },
  'tri-saw': { name: 'Triangle → Saw', category: 'Basic', gen: () => morphKeys([tri(), saw()], N) },
  'saw-square': { name: 'Saw → Square', category: 'Basic', gen: () => morphKeys([saw(), square()], N) },
  'analog-saw': { name: 'Analog Saw', category: 'Basic', gen: () => sweep((k, t) => SAW(k) * lp2(k, 400 - t * 360, 0.6) * (1 + 0.15 * Math.sin(k * 0.7 + t * 3)), 16) },
  // ---- PWM
  pwm: { name: 'PWM Sweep', category: 'PWM', gen: () => Array.from({ length: N }, (_, i) => pulse(0.5 - (i / (N - 1)) * 0.48)) },
  'pwm-saw': { name: 'PWM Saw', category: 'PWM', gen: () => shape((x, t) => { const w = 1 - t * 0.9; return x < w ? 2 * (x / w) - 1 : -1; }) },
  'pwm-dual': { name: 'Dual Pulse', category: 'PWM', gen: () => shape((x, t) => { const w = 0.05 + t * 0.2; return (x < w ? 1 : 0) + (x >= 0.5 && x < 0.5 + w * (1 - t * 0.5) ? 1 : 0) - 2 * w * (1.5 - t * 0.25); }) },
  trapezoid: { name: 'Trapezoid', category: 'PWM', gen: () => shape((x, t) => { const s = 0.25 - t * 0.245; const y = x < s ? x / s : x < 0.5 - s ? 1 : x < 0.5 + s ? 1 - (x - 0.5 + s) / s : x < 1 - s ? -1 : -1 + (x - 1 + s) / s; return Math.max(-1, Math.min(1, y)); }) },
  'pwm-sync': { name: 'Pulse Sync', category: 'PWM', gen: () => shape((x, t) => { const r = 1 + t * 5; const p = (x * r) % 1; return p < 0.5 * (1 - t * 0.6) ? 1 : -1; }) },
  // ---- Harmonic
  'harm-add': { name: 'Harmonic Series', category: 'Harmonic', gen: () => sweep((k, t) => { const n = 1 + t * 47; return k <= n ? (k <= n - 1 ? 1 : n - Math.floor(n)) / Math.sqrt(k) : 0; }) },
  'odd-add': { name: 'Odd Harmonics', category: 'Harmonic', gen: () => sweep((k, t) => { const n = 1 + t * 63; return k % 2 && k <= n ? 1 / Math.sqrt(k) : 0; }) },
  'even-add': { name: 'Even Harmonics', category: 'Harmonic', gen: () => sweep((k, t) => { const n = 2 + t * 62; return k === 1 ? 1 : k % 2 === 0 && k <= n ? 0.8 / Math.sqrt(k) : 0; }) },
  'harm-peak': { name: 'Harmonic Peak', category: 'Harmonic', gen: () => sweep((k, t) => { const c = 1 + t * 40; return Math.exp(-(((k - c) / (1.2 + t * 2)) ** 2)) + (k === 1 ? 0.3 : 0); }) },
  'saw-lp': { name: 'Saw Filter Sweep', category: 'Harmonic', gen: () => sweep((k, t) => SAW(k) * lp2(k, 1.2 * Math.pow(200, t))) },
  'square-lp': { name: 'Square Filter Sweep', category: 'Harmonic', gen: () => sweep((k, t) => SQUARE(k) * lp2(k, 1.5 * Math.pow(150, t))) },
  'saw-reso': { name: 'Resonant Saw', category: 'Harmonic', gen: () => sweep((k, t) => SAW(k) * lp2(k, 2 * Math.pow(60, t), 6)) },
  organ: { name: 'Drawbar Organ', category: 'Harmonic', gen: () => {
    const sets = [[1, 0, 0.8, 0, 0, 0, 0, 0], [1, 1, 0.8, 0.6, 0, 0, 0, 0], [1, 1, 1, 1, 0.8, 0, 0.6, 0], [1, 0.4, 1, 0.8, 1, 0.8, 1, 0.8]];
    const harm = [1, 2, 3, 4, 6, 8, 10, 12];
    return morphKeys(sets.map((s) => frameFromHarmonics(spec((k) => { const j = harm.indexOf(k); return j >= 0 ? s[j] / (1 + j * 0.2) : 0; }, 16))), N);
  } },
  'spectral-comb': { name: 'Spectral Comb', category: 'Harmonic', gen: () => sweep((k, t) => SAW(k) * (0.5 + 0.5 * Math.cos(TAU * k / (2 + t * 14)))) },
  // ---- Formant / vowel
  'vowel-aeiou': { name: 'Vowels A-E-I-O-U', category: 'Formant', gen: () => vowelPath(['a', 'e', 'i', 'o', 'u']) },
  'vowel-oa': { name: 'Vowels O-A-E', category: 'Formant', gen: () => vowelPath(['u', 'o', 'a', 'e']) },
  'formant-sweep': { name: 'Formant Sweep', category: 'Formant', gen: () => sweep((k, t) => formantAmp(k, [[250 + t * 3200, 120 + t * 200, 1]], 0.6)) },
  'formant-dual': { name: 'Dual Formant', category: 'Formant', gen: () => sweep((k, t) => formantAmp(k, [[300 + t * 900, 90, 1], [2600 - t * 1500, 150, 0.6]], 0.8)) },
  talkbox: { name: 'Talkbox', category: 'Formant', gen: () => sweep((k, t) => { const x = t * 4, j = Math.min(3, Math.floor(x)); const seq = ['o', 'a', 'e', 'i', 'a']; return formantAmp(k, lerpForms(VOWELS[seq[j]], VOWELS[seq[j + 1]], x - j), 0.2) * 1.6; }) },
  // ---- Vocal-ish
  'vox-ah': { name: 'Vox Ah', category: 'Vocal', gen: () => { const r = rnd(7); return sweep((k, t) => formantAmp(k, VOWELS.a, 1.2 - t * 0.6) * (1 + 0.25 * (r() - 0.5)), 16); } },
  choir: { name: 'Choir', category: 'Vocal', gen: () => { const r = rnd(11); const ph = spec(() => r() * TAU); return sweep((k, t) => formantAmp(k, lerpForms(VOWELS.o, VOWELS.a, t), 1.4), 32, () => ph); } },
  'vox-ee-oo': { name: 'Vox Ee-Oo', category: 'Vocal', gen: () => vowelPath(['i', 'e', 'o', 'u'], 32) },
  // ---- FM
  'fm-1-1': { name: 'FM 1:1', category: 'FM', gen: () => shape((x, t) => pm(1, 1, t * 6)(x)) },
  'fm-1-2': { name: 'FM 1:2', category: 'FM', gen: () => shape((x, t) => pm(1, 2, t * 5)(x)) },
  'fm-1-3': { name: 'FM 1:3', category: 'FM', gen: () => shape((x, t) => pm(1, 3, t * 4)(x)) },
  'fm-2-1': { name: 'FM 2:1', category: 'FM', gen: () => shape((x, t) => pm(2, 1, t * 5)(x) * 0.8 + Math.sin(TAU * x) * 0.2) },
  'fm-feedback': { name: 'FM Feedback', category: 'FM', gen: () => shape((x, t) => fbOsc(t * 1.5)(x)) },
  'fm-bell': { name: 'FM Bell', category: 'FM', gen: () => shape((x, t) => 0.6 * pm(1, 7, 1 + t * 3)(x) + 0.4 * pm(3, 5, t * 2)(x)) },
  'fm-growl': { name: 'FM Growl', category: 'FM', gen: () => shape((x, t) => Math.tanh(1.5 * pm(1, 2, 2 + 6 * t)(x) + 0.6 * Math.sin(TAU * 3 * x + t * 4 * Math.sin(TAU * x)))) },
  // ---- Digital / chiptune
  'nes-pulse': { name: 'NES Pulse', category: 'Digital', gen: () => [0.125, 0.25, 0.5, 0.75].flatMap((w) => Array(4).fill(0).map(() => bandlimit((x) => (x < w ? 1 : -1)))) },
  'nes-tri': { name: 'NES Triangle', category: 'Digital', gen: () => shape((x, t) => { const steps = 16 - Math.round(t * 12); const y = x < 0.5 ? 4 * x - 1 : 3 - 4 * x; return Math.round(y * steps / 2) / (steps / 2); }, 16) },
  bitcrush: { name: 'Bitcrush', category: 'Digital', gen: () => shape((x, t) => quant(0.5 * Math.sin(TAU * x) + 0.5 * (2 * x - 1) * t, 8 - t * 6), 32) },
  'digital-steps': { name: 'Digital Steps', category: 'Digital', gen: () => shape((x, t) => { const s = Math.round(32 - t * 28); return Math.floor(x * s) / s * 2 - 1; }, 32) },
  'ppg-sweep': { name: 'PPG Sweep', category: 'Digital', gen: () => { const r = rnd(23); const keys = Array.from({ length: 8 }, (_, j) => frameFromHarmonics(spec((k) => (k <= 4 + j * 6 && r() < 0.55 ? (0.4 + r()) / Math.pow(k, 0.7) : 0) + (k === 1 ? 0.5 : 0), 64))); return morphKeys(keys, N); } },
  gameboy: { name: 'Game Boy Wave', category: 'Digital', gen: () => { const waves = [[0, 4, 8, 12, 15, 12, 8, 4], [15, 15, 15, 15, 0, 0, 0, 0], [0, 2, 5, 9, 13, 15, 10, 3], [8, 15, 8, 3, 0, 3, 8, 12]]; return morphKeys(waves.map((w) => bandlimit((x) => w[Math.floor(x * w.length) % w.length] / 7.5 - 1)), 32); } },
  'sample-hold': { name: 'Sample & Hold', category: 'Digital', gen: () => { const r = rnd(31); return Array.from({ length: 16 }, () => { const v = Array.from({ length: 16 }, () => r() * 2 - 1); return removeDC(bandlimit((x) => v[Math.floor(x * 16)])); }); } },
  // ---- PADsynth-like
  'pad-warm': { name: 'Pad Warm', category: 'PAD', gen: () => padFrames(101, (k) => Math.exp(-((k - 1) / 18)) / Math.sqrt(k)) },
  'pad-bright': { name: 'Pad Bright', category: 'PAD', gen: () => padFrames(102, (k) => 1 / Math.pow(k, 0.7)) },
  'pad-glass': { name: 'Pad Glass', category: 'PAD', gen: () => padFrames(103, (k) => (k === 1 ? 0.6 : 0) + Math.exp(-(((k - 24) / 10) ** 2)) * 0.7 + Math.exp(-(((k - 60) / 16) ** 2)) * 0.4) },
  'pad-hollow': { name: 'Pad Hollow', category: 'PAD', gen: () => padFrames(104, (k) => (k % 2 ? 1 : 0.15) / k) },
  'pad-evolve': { name: 'Pad Evolve', category: 'PAD', gen: () => padFrames(105, (k) => 1 / Math.pow(k, 0.9), 64, 0.8) },
  // ---- Noise-ish
  'noise-cycle': { name: 'Noise Cycles', category: 'Noise', gen: () => { const r = rnd(41); return Array.from({ length: 32 }, () => frameFromHarmonics(spec((k) => (0.3 + r()) / Math.pow(k, 0.5)), spec(() => r() * TAU))); } },
  grit: { name: 'Grit', category: 'Noise', gen: () => { const r = rnd(43); return sweep((k, t) => SAW(k) * (1 + t * 3 * (r() - 0.5)), 32, () => spec(() => r() * TAU * 0.3)); } },
  rust: { name: 'Rust', category: 'Noise', gen: () => { const r = rnd(47); return Array.from({ length: 32 }, (_, i) => frameFromHarmonics(spec((k) => (r() < 0.3 + (i / 31) * 0.6 ? r() : 0) / Math.pow(k, 0.4)), spec(() => r() * TAU))); } },
  // ---- Shaping
  fold: { name: 'Wavefold', category: 'Shaping', gen: () => shape((x, t) => Math.sin((1 + t * 7) * Math.sin(TAU * x))) },
  drive: { name: 'Overdrive', category: 'Shaping', gen: () => shape((x, t) => Math.tanh((1 + t * t * 20) * Math.sin(TAU * x)) / Math.tanh(1 + t * t * 20)) },
  'phase-dist': { name: 'Phase Distortion', category: 'Shaping', gen: () => shape((x, t) => { const d = 0.5 - t * 0.48; const p = x < d ? (x / d) * 0.5 : 0.5 + ((x - d) / (1 - d)) * 0.5; return Math.cos(TAU * p); }) },
  'sync-sweep': { name: 'Hard Sync Sweep', category: 'Shaping', gen: () => shape((x, t) => { const r = 1 + t * 7; return 2 * ((x * r) % 1) - 1; }) },
  'cz-reso': { name: 'Resonance (CZ)', category: 'Shaping', gen: () => shape((x, t) => { const r = 1 + t * 11; return (1 - x) * Math.cos(TAU * r * x); }) },
  asym: { name: 'Asymmetric', category: 'Shaping', gen: () => shape((x, t) => { const s = Math.sin(TAU * x); return s > 0 ? Math.tanh(s * (1 + t * 6)) : s * (1 - t * 0.6); }) },
};

export const FACTORY_CATEGORIES = ['Basic', 'PWM', 'Harmonic', 'Formant', 'Vocal', 'FM', 'Digital', 'PAD', 'Noise', 'Shaping'];

const cache = new Map();
/** Frames of a factory table (cached; generated on first use, normalized, DC-free). null for unknown ids. */
export function factoryFrames(id) {
  const t = FACTORY_TABLES[id];
  if (!t) return null;
  if (!cache.has(id)) cache.set(id, normalizeFrames(t.gen().map(removeDC), 0.95));
  return cache.get(id);
}

/** Options for pickers: [{value, label, group}] (factory tables; user tables are added by the UI). */
export function factoryTableOptions() {
  return Object.entries(FACTORY_TABLES).map(([value, t]) => ({ value, label: t.name, group: t.category }));
}
